/**
 * Loads the personal particle portrait generated by scripts/build_portrait.py
 * (segmentation + face-landmark depth + photo luminance) and prepares the
 * GPU attributes, the "data sphere" morph targets and a sparse line network.
 */

export type PortraitMeta = {
  count: number;
  scale: number;
  bounds: { minY: number; maxY: number; minX: number; maxX: number };
};

export type PortraitData = {
  count: number;
  positions: Float32Array; // xyz
  normals: Float32Array; // xyz
  meta: Float32Array; // lum, region, edge
  randoms: Float32Array; // 4 per point
  /** Formation targets (animated further in the shader). */
  sphere: Float32Array; // xyz on a flow sphere (radius ~1.4, centred at origin)
  terrain: Float32Array; // x, row-z, height seed — a wide undulating landscape
  galaxy: Float32Array; // xyz on a three-arm spiral disc (flat, centred at origin)
  linePositions: Float32Array;
  lineSeeds: Float32Array; // seed, unused
  bounds: PortraitMeta["bounds"];
};

// Region codes written by the build script.
export const REGION = { face: 0, hair: 1, skin: 2, clothes: 3, halo: 4, back: 5 } as const;

export async function loadPortrait(base: string, limit?: number): Promise<PortraitData> {
  const [metaRes, binRes] = await Promise.all([fetch(`${base}/meta.json`), fetch(`${base}/points.bin`)]);
  if (!metaRes.ok || !binRes.ok) throw new Error("portrait data missing");
  const meta = (await metaRes.json()) as PortraitMeta;
  const buf = await binRes.arrayBuffer();
  const total = meta.count;
  const n = Math.min(limit ?? total, total); // file is shuffled, so a prefix is an even subset

  const xyz = new Int16Array(buf, 0, total * 3);
  const nrm = new Int8Array(buf, total * 6, total * 2);
  const att = new Uint8Array(buf, total * 8, total * 3);

  const positions = new Float32Array(n * 3);
  const normals = new Float32Array(n * 3);
  const metaAttr = new Float32Array(n * 3);
  const randoms = new Float32Array(n * 4);
  const sphere = new Float32Array(n * 3);
  const terrain = new Float32Array(n * 3);
  const galaxy = new Float32Array(n * 3);

  for (let i = 0; i < n; i++) {
    positions[i * 3] = xyz[i * 3] * meta.scale;
    positions[i * 3 + 1] = xyz[i * 3 + 1] * meta.scale;
    positions[i * 3 + 2] = xyz[i * 3 + 2] * meta.scale;
    const nx = nrm[i * 2] / 127, ny = nrm[i * 2 + 1] / 127;
    const nz = Math.sqrt(Math.max(0, 1 - nx * nx - ny * ny));
    const region = att[i * 3 + 1];
    normals[i * 3] = nx; normals[i * 3 + 1] = ny; normals[i * 3 + 2] = region === 5 ? -nz : nz;
    metaAttr[i * 3] = att[i * 3] / 255;
    metaAttr[i * 3 + 1] = region;
    metaAttr[i * 3 + 2] = att[i * 3 + 2] / 255;
    for (let k = 0; k < 4; k++) randoms[i * 4 + k] = Math.random();
    writeFormations(i, sphere, terrain, galaxy);
  }
  return finish(n, positions, normals, metaAttr, randoms, sphere, terrain, galaxy, meta.bounds, true);
}

const gauss = () => {
  let u = 0, v = 0;
  while (u === 0) u = Math.random();
  while (v === 0) v = Math.random();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
};

/** Abstract particle set (no portrait file needed) for pages that only use sphere / terrain / galaxy. */
export function makeAbstract(n: number): PortraitData {
  const positions = new Float32Array(n * 3);
  const normals = new Float32Array(n * 3);
  const metaAttr = new Float32Array(n * 3);
  const randoms = new Float32Array(n * 4);
  const sphere = new Float32Array(n * 3);
  const terrain = new Float32Array(n * 3);
  const galaxy = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) {
    normals[i * 3 + 2] = 1;
    metaAttr[i * 3 + 1] = REGION.halo;
    for (let k = 0; k < 4; k++) randoms[i * 4 + k] = Math.random();
    writeFormations(i, sphere, terrain, galaxy);
  }
  return finish(n, positions, normals, metaAttr, randoms, sphere, terrain, galaxy, { minY: -3, maxY: 1, minX: -2, maxX: 2 }, false);
}

function writeFormations(i: number, sphere: Float32Array, terrain: Float32Array, galaxy: Float32Array) {
    // Flow sphere: particles sit on ~44 latitude bands (the shader counter-rotates them),
    // with a thin inner core so the sphere has depth.
    {
      const core = Math.random() < 0.12;
      const band = Math.floor(Math.random() * 44);
      const lat = ((band + 0.5) / 44) * Math.PI - Math.PI / 2 + gauss() * 0.012;
      const lon = Math.random() * Math.PI * 2;
      const R = core ? 0.35 + Math.random() * 0.75 : 1.42 + gauss() * 0.02;
      sphere[i * 3] = Math.cos(lat) * Math.cos(lon) * R;
      sphere[i * 3 + 1] = Math.sin(lat) * R;
      sphere[i * 3 + 2] = Math.cos(lat) * Math.sin(lon) * R;
    }
    // Data terrain: 70 scan rows receding into the distance (heights are animated in the shader).
    {
      const row = Math.floor(Math.random() * 70);
      terrain[i * 3] = (Math.random() - 0.5) * 16;
      terrain[i * 3 + 1] = row;
      terrain[i * 3 + 2] = Math.random();
    }
    // Galaxy: three logarithmic spiral arms plus a bright bulge.
    {
      const bulge = Math.random() < 0.18;
      const r = bulge ? Math.abs(gauss()) * 0.35 : 0.25 + Math.pow(Math.random(), 0.75) * 3.1;
      const arm = Math.floor(Math.random() * 3);
      const th = arm * ((Math.PI * 2) / 3) + Math.log(r + 0.3) * 2.4 + gauss() * (0.28 / (r + 0.35));
      galaxy[i * 3] = Math.cos(th) * r + gauss() * 0.04;
      galaxy[i * 3 + 1] = gauss() * (bulge ? 0.12 : 0.05 * (1.2 - r / 3.4));
      galaxy[i * 3 + 2] = Math.sin(th) * r + gauss() * 0.04;
    }
}

function finish(
  n: number, positions: Float32Array, normals: Float32Array, metaAttr: Float32Array, randoms: Float32Array,
  sphere: Float32Array, terrain: Float32Array, galaxy: Float32Array, bounds: PortraitMeta["bounds"], withLines: boolean,
): PortraitData {
  // Sparse network lines across the sweatshirt (kept off the face so features stay clean).
  const cell = 0.09;
  const grid = new Map<string, number[]>();
  const anchors: number[] = [];
  for (let i = 0; withLines && i < n && anchors.length < 1800; i++) {
    if (metaAttr[i * 3 + 1] !== REGION.clothes || Math.random() > 0.25) continue;
    anchors.push(i);
    const key = `${Math.floor(positions[i * 3] / cell)},${Math.floor(positions[i * 3 + 1] / cell)}`;
    (grid.get(key) ?? grid.set(key, []).get(key)!).push(i);
  }
  const lines: number[] = [];
  const seeds: number[] = [];
  for (const j of anchors) {
    const x = positions[j * 3], y = positions[j * 3 + 1], z = positions[j * 3 + 2];
    const cx = Math.floor(x / cell), cy = Math.floor(y / cell);
    let links = 0;
    for (let a = -1; a <= 1 && links < 2; a++) for (let b = -1; b <= 1 && links < 2; b++) {
      for (const k of grid.get(`${cx + a},${cy + b}`) ?? []) {
        if (k <= j || links >= 2) continue;
        const dx = positions[k * 3] - x, dy = positions[k * 3 + 1] - y, dz = positions[k * 3 + 2] - z;
        const d2 = dx * dx + dy * dy + dz * dz;
        if (d2 > 0.0016 && d2 < 0.0081) {
          lines.push(x, y, z, positions[k * 3], positions[k * 3 + 1], positions[k * 3 + 2]);
          const s = Math.random();
          seeds.push(s, 0, s, 0);
          links++;
        }
      }
    }
  }

  return {
    count: n, positions, normals, meta: metaAttr, randoms, sphere, terrain, galaxy,
    linePositions: new Float32Array(lines), lineSeeds: new Float32Array(seeds), bounds,
  };
}
